import React, {useCallback, useEffect, useRef, useState} from 'react'

import {ChatPanel} from './Components/ChatPanel'
import {EmbeddedContentPreview} from './Components/EmbeddedContentPreview'
import {Header} from './Components/Header'
import styles from './CopilotImmersiveEmbedded.module.css'

const environment = relayEnvironmentWithMissingFieldHandlerForNode()

interface CopilotImmersiveEmbeddedProps extends CopilotImmersivePayload {
  pendingOpenEvent?: OpenCopilotChatEvent | null
  onPendingEventHandled?: () => void
}

export function CopilotImmersiveEmbedded({
  pendingOpenEvent,
  onPendingEventHandled,
  ...payloadProps
}: CopilotImmersiveEmbeddedProps) {
  const inputRef = useRef<HTMLTextAreaElement>(null)
  return (
    <RelayEnvironmentProvider environment={environment}>
      <AppPayloadContext value={payloadProps}>
        <CopilotImmersiveProviders payload={payloadProps} mode="assistive">
          <CopilotHeaderButton
            inputRef={inputRef}
            pendingOpenEvent={pendingOpenEvent}
            onPendingEventHandled={onPendingEventHandled}
          />
        </CopilotImmersiveProviders>
      </AppPayloadContext>
    </RelayEnvironmentProvider>
  )
}

type CopilotHeaderButtonProps = {
  inputRef: React.RefObject<HTMLTextAreaElement | null>
  pendingOpenEvent?: OpenCopilotChatEvent | null
  onPendingEventHandled?: () => void
}
const CopilotHeaderButton = ({inputRef, pendingOpenEvent, onPendingEventHandled}: CopilotHeaderButtonProps) => {
  const manager = useChatManager()
  const state = useChatStateValues(
    'selectedThreadID',
    'threads',
    'currentTopic',
    'currentView',
    'availableModels',
    'chatVisibleSettingPath',
    'chatIsOpen',
    'threadsLoading',
  )
  const selectedThread = getSelectedThread(state)
  const {currentTopic} = state
  const {screenSize} = useScreenSize()
  // const {licenseType} = useEntitlement()
  const defaultModel = useDefaultModel(state.availableModels)
  const initialRenderRef = useRef(true)
  const hasPersistedRef = useRef(false)
  // Track whether we're in the initial loading state (reopening chat from localStorage)
  const [isInitialLoading, setIsInitialLoading] = useState(() => {
    // Only show loading if we're going to reopen chat from localStorage
    return !copilotLocalStorage.getCollapsedState() && screenSize > ScreenSize.large
  })

  useEffect(() => {
    if (pendingOpenEvent) {
      // Send analytics for header button clicks
      if (pendingOpenEvent.payload.source === 'header') {
        sendEvent('dotcom_chat.activate', {
          target: 'GLOBAL_COPILOT_MENU_HEADER_TO_IMMERSIVE',
          mode: 'global_nav',
        })
      }
      // When opened from anywhere except the global nav header button,
      // switch to ask mode if currently in agent mode
      if (
        pendingOpenEvent.payload.source !== 'header' &&
        copilotLocalStorage.getActiveMode() === ModeSupportName.Agent
      ) {
        copilotLocalStorage.setActiveMode(ModeSupportName.Ask)
      }
      void manager.handleOpenPanelEvent(selectedThread, pendingOpenEvent, state.chatIsOpen, currentTopic, defaultModel)
      onPendingEventHandled?.()
    }
  }, [pendingOpenEvent, onPendingEventHandled, manager, selectedThread, state.chatIsOpen, currentTopic, defaultModel])

  useEffect(() => {
    return subscribeAddCopilotChatReference((e: AddCopilotChatReferenceEvent) => {
      void manager.handleAddReferenceEvent(e)
    })
  }, [manager])

  useEffect(() => {
    return subscribeSymbolChanged((e: SymbolChangedEvent) => {
      void manager.handleSymbolChangedEvent(e)
    })
  }, [manager])

  useEffect(() => {
    return subscribeSearchCopilot((e: SearchCopilotEvent) => {
      void manager.handleSearchCopilotEvent(e, defaultModel)
    })
  }, [manager, defaultModel])

  // Run once on initial render to check if we should open chat on page load
  useEffect(() => {
    if (initialRenderRef.current) {
      initialRenderRef.current = false
      if (!copilotLocalStorage.getCollapsedState() && screenSize > ScreenSize.large) {
        // Create a synthetic event to trigger proper thread loading
        // Use source: 'header' to preserve the current mode (don't switch from Task to Ask)
        const syntheticEvent = new OpenCopilotChatEvent({
          intent: CopilotChatIntents.conversation,
          source: 'header',
        })
        void manager.handleOpenPanelEvent(selectedThread, syntheticEvent, state.chatIsOpen, currentTopic, defaultModel)
      } else {
        // Not reopening, so clear the loading state immediately
        // eslint-disable-next-line react-hooks/set-state-in-effect
        setIsInitialLoading(false)
      }
    }
  }, [
    manager,
    screenSize,
    selectedThread,
    state.chatVisibleSettingPath,
    state.currentView,
    state.chatIsOpen,
    currentTopic,
    defaultModel,
  ])

  // Clear initial loading state once we have a selected thread or confirmed there's no thread to restore
  useEffect(() => {
    if (
      isInitialLoading &&
      (selectedThread ||
        ((state.threadsLoading?.state === 'loaded' || state.threadsLoading?.state === 'error') &&
          !state.selectedThreadID))
    ) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setIsInitialLoading(false)
    }
  }, [isInitialLoading, selectedThread, state.chatIsOpen, state.selectedThreadID, state.threadsLoading])

  // Persist chat open state to localStorage when it changes
  // This allows the chat to reopen after hard navigations
  useEffect(() => {
    // Skip the first run to avoid overwriting saved state before we read it in the initial render effect
    if (!hasPersistedRef.current) {
      hasPersistedRef.current = true
      return
    }
    copilotLocalStorage.setCollapsedState(!state.chatIsOpen)
  }, [state.chatIsOpen])

  return (
    <div className={styles.CopilotChatContainer} data-testid="copilot-immersive-embedded-header-button">
      <EmbeddedImmersive inputRef={inputRef} isInitialLoading={isInitialLoading} />
    </div>
  )
}

function EmbeddedImmersive({
  inputRef,
  isInitialLoading,
}: {
  inputRef: React.RefObject<HTMLTextAreaElement | null>
  isInitialLoading: boolean
}) {
  const {chatIsOpen, currentView} = useChatStateValues('chatIsOpen', 'currentView')
  const isContentPreviewOpen = useContentPreviewOpen()
  const {closePreviewPane} = useContentPreview()
  const manager = useChatManager()
  const {panelWidth, panelHeight, startResize, onResizerKeyDown} = useResizablePanel()
  const staffDialogRef = useRef<HTMLDivElement>(null)
  const [showStaffDialog, setShowStaffDialog] = useState<DialogType>(DialogType.None)

  // Force icon-only mode in the toolbar when panel is narrow (below 544px which is the narrow breakpoint)
  const forceIconOnly = panelWidth < 544

  const handleCloseChat = useCallback(() => {
    manager.closeChat()
  }, [manager])

  const handleCloseContentPreview = useCallback(() => {
    closePreviewPane()
  }, [closePreviewPane])
  return (
    chatIsOpen && (
      <OverlayDirectionProvider preferredOverlaySide="outside-top">
        <ChatPanel
          handleClose={handleCloseChat}
          panelWidth={panelWidth}
          panelHeight={panelHeight}
          startResize={startResize}
          onResizerKeyDown={onResizerKeyDown}
          initialFocusRef={inputRef}
          staffDialogRef={staffDialogRef}
        >
          <Header
            staffDialogRef={staffDialogRef}
            showStaffDialog={showStaffDialog}
            setShowStaffDialog={setShowStaffDialog}
          />
          {isInitialLoading ? (
            <div className={styles.loadingContainer}>
              <Spinner size="large" srText="Loading conversation..." />
            </div>
          ) : currentView === 'list' ? (
            <ThreadListView />
          ) : (
            <ConversationView
              attachmentMenuSide="outside-top"
              isMobile
              textAreaRef={inputRef}
              forceIconOnly={forceIconOnly}
              isEmbedded
            />
          )}
        </ChatPanel>
        {isContentPreviewOpen && (
          <Dialog
            className={styles.contentPreviewDialog}
            onClose={handleCloseContentPreview}
            position={{narrow: 'fullscreen', regular: 'fullscreen', wide: 'fullscreen'}}
            title="Content Preview"
            renderHeader={() => null}
            renderBody={() => <EmbeddedContentPreview inputRef={inputRef} />}
          />
        )}
      </OverlayDirectionProvider>
    )
  )
}
